from collections import deque

def transform(grid):
 h,w=len(grid),len(grid[0]); bg=max(set(x for row in grid for x in row), key=lambda x:sum(row.count(x) for row in grid))
 out=[row[:] for row in grid]; seen=set()
 for r in range(h):
  for c in range(w):
   col=grid[r][c]
   if col==bg or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); comp=[]
   while q:
    y,x=q.pop(); comp.append((y,x))
    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
     yy,xx=y+dy,x+dx
     if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==col: seen.add((yy,xx)); q.append((yy,xx))
   if len(comp)==1: out[r][c]=bg
 return out
out=transform(grid)
print(out)

def denoise(g):
 h,w=len(g),len(g[0]); o=[r[:] for r in g]
 from collections import Counter
 for r in range(h):
  for c in range(w):
   vals=[g[y][x] for y in range(max(0,r-1),min(h,r+2)) for x in range(max(0,c-1),min(w,c+2)) if (y,x)!=(r,c)]
   cnt=Counter(vals); best,n=cnt.most_common(1)[0]
   if n>=5 and g[r][c]!=best: o[r][c]=best
 return o
