from collections import Counter
# replace anomalous colors 1,7,8 with nearest dominant valid-color local majority; use nearest cells by Manhattan, tie majority
valid={0,2,3,5,9};
def fix(g):
 o=[row[:] for row in g]; h=len(g);w=len(g[0])
 for r in range(h):
  for c in range(w):
   if g[r][c] not in valid:
    for rad in range(1,max(h,w)):
     vals=[]
     for y in range(max(0,r-rad),min(h,r+rad+1)):
      for x in range(max(0,c-rad),min(w,c+rad+1)):
       if abs(y-r)+abs(x-c)<=rad and g[y][x] in valid: vals.append(g[y][x])
     if vals:
      o[r][c]=Counter(vals).most_common(1)[0][0]; break
 return o
