def filt(g,threshold=4):
 h,w=len(g),len(g[0]); bg=Counter(x for row in g for x in row).most_common(1)[0][0]; o=[row[:] for row in g]; seen=set()
 for r in range(h):
  for c in range(w):
   if g[r][c]==bg or (r,c) in seen: continue
   col=g[r][c]; st=[(r,c)];seen.add((r,c));co=[]
   while st:
    y,x=st.pop();co.append((y,x))
    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
     yy,xx=y+dy,x+dx
     if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and g[yy][xx]==col:seen.add((yy,xx));st.append((yy,xx))
   if len(co)<threshold:
    for y,x in co:o[y][x]=bg
 return o
